inline constexpr std::size_t kGuiThemeCount = sizeof(kGuiThemes) / sizeof(kGuiThemes[0]);

// `default`, the templates' and the construction state's row (device_config.h).
inline constexpr std::size_t kGuiDefaultTheme = 0;
static_assert(std::string_view(kGuiThemes[kGuiDefaultTheme].slug) == "default");

// THE ONE GRAMMAR OWNER of the `theme` key: the row whose slug is `slug`, or
// nullptr when no theme bears it (the reader's hard fail, the editor's
// refusal; device_config.h's kThemeGrammarReason).
constexpr const GuiTheme* find_gui_theme(std::string_view slug) {
    for (const GuiTheme& t : kGuiThemes)
        if (slug == t.slug) return &t;
    return nullptr;
}

// No two rows share a slug (the tool refuses a duplicate; this pins it).
constexpr bool gui_theme_slugs_unique() {
    for (std::size_t i = 0; i < kGuiThemeCount; ++i)
        for (std::size_t j = i + 1; j < kGuiThemeCount; ++j)
            if (std::string_view(kGuiThemes[i].slug) == kGuiThemes[j].slug)
                return false;
    return true;
}
static_assert(gui_theme_slugs_unique());
